import sys
sys.path.insert(0, ".")
from pager import page
for N in [0, 1, 5, 9, 10, 11, 20, 25, 37, 100]:
    xs = list(range(N))
    for size in [1, 3, 10, 7]:
        for n in range(0, N // size + 3):
            if size == 10:
                if page(xs, n) != xs[n*size:(n+1)*size]:
                    sys.exit(1)
            if page(xs, n, size) != xs[n*size:(n+1)*size]:
                sys.exit(1)
            if page(xs, n, size=size) != xs[n*size:(n+1)*size]:
                sys.exit(1)
sys.exit(0)
